import { BASE_URL, TARGET, VERSION } from './constants.js';

const indicatorParams = { addon: TARGET, addonversion: VERSION };

export const generateURL = (pathname, extraParams) => {
  const parsed = new URL(BASE_URL);
  const params = new URLSearchParams({ ...extraParams, ...indicatorParams });
  parsed.pathname = pathname;
  parsed.search = params.toString();
  return parsed.toString();
};
